BASE_MAP = os.path.join(ROOT, "_maps", "map_files", "HippieStation", "hippiestation.dmm")
BBOX = (162, 82, 208, 128)

# ---------------------------------------------------------------- inputs: what the outline fixes
WEST_DOOR = (165, 115)          # onto the west hall: the east-west street runs from it
SOUTH_DOOR = (180, 87)          # onto south maintenance: the north-south street runs from it
LAUNCH_SHUTTERS = [(x, 127) for x in (166, 167, 168, 169)]   # mech bay onto the main hall
MECH_MAINT = (164, 126)
CHUTE = [(189, 121), (190, 121), (191, 121)]                # cargo's delivery chute into R&D
DRIVER_RUN = [(205, 104), (206, 104), (207, 104)]           # mass driver door and its airless run
TOXINS_MAINT = (197, 103)       # toxins' door to the science maintenance room (bombs walk to the launch room)
KEEP = LAUNCH_SHUTTERS + [MECH_MAINT, WEST_DOOR, SOUTH_DOOR] + CHUTE + DRIVER_RUN


def in_zone(a):
    return a.startswith(("/area/science", "/area/crew_quarters/heads/hor", "/area/security/checkpoint/science")) \
        and a != "/area/science/test_area"


# ---------------------------------------------------------------- parameters (change one, everything re-flows)
