for _i, _p in enumerate(PENS):
    ROOM_TABLE[_p] = dict(area=XENO, floor=ENG, name="Containment Pen", main=False, label="P%d" % (_i + 1),
                          asset="pen", pen=_i + 1)


def plans(P):
    """The slicing tree, hung on the outline's doors. Free tiles: x165..196, y85..126; the launch room apart."""
    x0, y0, x1, y1 = 165, 85, 196, 126
    st = P["street"]
    ew_top = WEST_DOOR[1]                    # the east-west street's top row is the west door's row
    ns_left = SOUTH_DOOR[0] - st // 2        # the north-south street is centred on the south door
    band_n = y1 - (ew_top + 2) + 1           # rooms between the main hall and the street
    sw, sd = P["surgery"]
    robo_w = ns_left - 1 - (x0 + P["mechbay"] + 1)
    robotics = Y((1.0, "robotics"), (sd, X((1.0, "robotics"), (sw, "surgery"))))
    north = X((P["mechbay"], "mechbay"), (robo_w, robotics), (st, "foyer"), (1.0, "rnd"))
    east_x = 190                             # the outline steps out east here (the delivery chute's corner)
    c = P["chamber"]
    explab = Y((1.0, "explab"), (c, X((1.0, "explab"), (c, "chamber"))))
    top = X((east_x - 1 - x0, Y((band_n, north), (st, "spine"))), (1.0, explab))
    xeno = Y((P["xenolab"], "xeno"),
             (1.0, X((P["pen"], Y((3, "pen1"), (3, "pen2"), (1.0, "pen3"))), (st, "pens"),
                     (1.0, Y((3, "pen4"), (1.0, "pen5"))))))
    west = Y((P["middle"], X((P["server"], "server"), (1.0, "rdoffice"))), (1.0, xeno))
    testing = X((1.0, "testing"), (P["testchamber"] + 2, "testchamber"))   # the outline's east ring takes two
    east = Y((P["middle"] + 1, X((P["post"], Y((3, "secpost"), (1.0, "cell"))), (1.0, "nanite"))),
             (P["toxins"], "toxins"), (1.0, testing))
    bottom = X((ns_left - 1 - x0, west), (st, "spine"), (1.0, east))
    main = Y((band_n + 1 + st, top), (1.0, bottom))
    launch = Y((4, "launch"), (2, "launchrun"))
    return [((x0, y0, x1, y1), main), ((202, 103, 207, 109), launch)]


def notch(geo):
    """The burn chamber stands against the pocket of space inside the outline: it vents there."""
    pocket = sorted(p for p in ((x, y) for x in range(BBOX[0], BBOX[2]) for y in range(BBOX[1], BBOX[3]))
                    if p not in geo.zone and geo.outside(p) == "space"
                    and (p[0] - 1, p[1]) in geo.zone and (p[0] + 1, p[1]) in geo.zone)
    return (pocket[0][0] + 1, pocket[0][1] - 1) if pocket else None


PIPE_E = ("/obj/machinery/atmospherics/pipe/simple/general/visible", {"dir": 4})
LINKS = [
    # kept as they are
    keep(WEST_DOOR, "spine"), keep(SOUTH_DOOR, "spine"), keep(MECH_MAINT, "mechbay"), keep(CHUTE[0], "rnd"),
    keep(DRIVER_RUN[0], "launchrun"),
] + [keep(p, "mechbay") for p in LAUNCH_SHUTTERS] + [
    # the public front on the main hall
    door("foyer", "hall", name="Research Division", glass=True, firedoor=True),
    glass("foyer", "hall", runs="door"),
    door("foyer", "spine", wide=3, type="biohazard", id="Biohazard"),
    desk("robotics", "hall", at=("x", 176), name="Robotics Desk", access="29", id="robotics_desk"),
    glass("robotics", "hall", runs="door"),
    desk("rnd", "hall", at=("x", 184), name="Research and Development Desk", one_access="7;29", id="rnd"),
    glass("rnd", "hall", runs="door"),
    glass("robotics", "foyer", span=(0.7, 1.0)),       # the front office only: the fabs need a solid wall
    glass("rnd", "foyer", span=(0.25, 1.0), inset=1),
    # robotics and the mech bay
    door("mechbay", "robotics", wide=3, type="shutter", id="robo_mechbay", name="mech bay shutters"),
    door("robotics", "spine", at=("x", 172), name="Robotics Lab", access="29"),
    door("surgery", "robotics", at=("tile", (173, 118)), name="Robotics Surgery", access="29", glass=True),
    glass("surgery", "robotics", runs="all"),
    door("rnd", "spine", name="Research and Development Lab", access="7"),
    door("explab", "spine", name="Experimentation Lab", access="7"),
    door("chamber", "explab", type="blast", id="telelab", name="Test Chamber", access="7"),
    glass("chamber", "explab"),
    # the middle band
    door("rdoffice", "spine", name="Research Director's Office", access="30", kind="command", glass=True),
    glass("rdoffice", "spine", inset=1),
    door("server", "rdoffice", name="Server Room", access="30", kind="command"),
    door("secpost", "spine", at=("tile", (182, 110)), name="Security Post - Science", access="63", kind="security",
         glass=True),
    glass("secpost", "spine", runs="door"),            # glass onto the crossroads; the other walls carry its alarms
    door("cell", "secpost", type="windoor", name="Holding Cell", access="63"),
    glass("cell", "secpost"),
    door("nanite", "spine", name="Nanite Lab", access="7", glass=True),
    # the south
    door("xeno", "spine", at=("y", 102), name="Xenobiology Lab", access="55"),
    door("pens", "xeno", wide=3, type="biohazard", id="xeno_containment"),
] + [ln for i, p in enumerate(PENS) for ln in (
    door(p, "pens", type="pen", id="xenobio%d" % (i + 1), name="Containment Pen", access="55"),
    glass(p, "pens"))] + [
    door("toxins", "spine", at=("y", 98), name="Toxins Lab", access="7"),
    door("testing", "spine", name="Testing Lab", access="47"),
    door("testchamber", "testing", type="blast", id="testlab", name="Test Chamber", access="47", extra=[PIPE_E]),
    glass("testchamber", "testing"),
    door("toxins", "maint", at=("tile", TOXINS_MAINT), name="Toxins Lab Maintenance", access="8"),
    door("launch", "maint", name="Toxins Launch Room", access="8"),
    glass("launch", "space"),                           # the watchers see the bomb go
    door("launch", "launchrun", at=("x", 202), type="windoor", name="Mass Driver Door", access="7"),
]


def graph(**over):
    P = dict(PARAMS)
    P.update(over)
    g = G.Graph(NAME, **P)
    g.add("outline", shell.outline, view="kind", base=BASE_MAP, bbox=BBOX, in_zone=in_zone, add=[TOXINS_MAINT], keep=KEEP)
    g.add("slice", shell.slice_rooms, view="rooms", plans=plans(P), rooms=ROOM_TABLE)
    g.add("stamp", shell.stamp, view="rooms", stamps=[("burn", notch, "burn", assets.burn_chamber())], rooms=ROOM_TABLE)
    g.add("tidy", shell.tidy, view="rooms")
    g.add("openings", shell.openings, view="rooms", links=LINKS)
    g.add("fields", shell.fields, view="fields")
    g.add("furnish", furnish.furnish, view="items", assets=assets.ASSETS)
    return g


# the blueprint forge.build reads (mapforge.py build blueprints/science_v3.py)
_graph = graph()
_geo = _graph.run()
_burn = _geo.attr.get("_anchor", {}).get("burn", (0, 0))
globals().update(emit.blueprint(_geo, NAME, extra=dict(
    STYLE="meta", DISPOSALS="route", DISPOSAL_ENDS={"deathsposal": (179, 71)}, BASE=BASE_MAP,
    # the burn chamber airlock's fill and drain join the station's air and waste lines
    TAPS={"supply": [((_burn[0] + 4, _burn[1] + 4), 2)], "scrubbers": [((_burn[0] + 4, _burn[1] + 1), 1)]})))


def main():
    g, geo = _graph, _geo
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = g.pictures(out)
    G.sheet(paths, os.path.join(out, NAME + "_nodes.png"), cols=4)
    G.draw(geo, "items", os.path.join(out, NAME + "_furnish_big.png"), tile=28, title="furnish")
    for n in geo.notes:
        print(n)
    for p in geo.problems:
        print("PROBLEM", p)
    print("pictures:", os.path.relpath(os.path.join(out, NAME + "_nodes.png"), ROOT))


WEDGE = [
    ("as built", {}),
    ("bigger servers, post, both test chambers", dict(server=5, chamber=4, post=4, testchamber=5)),
    ("longer pens, deeper toxins, wider surgery", dict(xenolab=6, toxins=10, surgery=(5, 2))),
    ("deeper middle band (pushes toxins off its vent pocket)", dict(middle=8)),
]


def wedge():
    """The same graph under different parameters, side by side: the proof it is generated, not drawn."""
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = []
    for i, (label, over) in enumerate(WEDGE):
        g = graph(**over)
        geo = g.run()
        path = os.path.join(out, "%s_wedge_%d.png" % (NAME, i))
        G.draw(geo, "items", path, tile=14, title="%s  (%d problems)" % (label, len(geo.problems)))
        paths.append(path)
        print("%-40s %d problems" % (label, len(geo.problems)))
        for p in geo.problems:
            print("   ", p)
    print("pictures:", os.path.relpath(G.sheet(paths, os.path.join(out, NAME + "_wedge.png"), cols=2), ROOT))


if __name__ == "__main__":
    wedge() if "--wedge" in sys.argv else main()
